1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Region;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "bulkSignupWarning", ignore = true)
36	    @Mapping(target = "capacityWarning", ignore = true)
37	    @Mapping(target = "identityKey", ignore = true)
38	    @Mapping(target = "possibleDuplicate", ignore = true)
39	    @Mapping(target = "possibleDuplicateOf", ignore = true)
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives the owner's {@code selfLink}: the canonical link to the owner, formatted
44	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner has no id (e.g. an
45	     * unpersisted owner), in which case the field is absent from the response.
46	     *
47	     * @param owner the owner being mapped
48	     * @return the owner's self link, or {@code null} when the owner has no id
49	     */
50	    default String selfLink(Owner owner) {
51	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
52	    }
53	
54	    /**
55	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
56	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
57	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
58	     *
59	     * @param owner the owner being mapped
60	     * @return the derived salutation
61	     */
62	    default String salutation(Owner owner) {
63	        String title = owner.getTitle();
64	        if (title == null || title.isBlank()) {
65	            return owner.getLastName();
66	        }
67	        return title + " " + owner.getLastName();
68	    }
69	
70	    /**
71	     * Derives the owner's {@code contactPreference} from the owner's own fields:
72	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
73	     *
74	     * @param owner the owner being mapped
75	     * @return the derived contact preference
76	     */
77	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
78	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
79	    }
80	
81	    /**
82	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
83	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
84	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
85	     * rather than repeated at each use.
86	     *
87	     * @param owner the owner being mapped
88	     * @return {@code true} when the owner has a non-blank email
89	     */
90	    default boolean hasEmail(Owner owner) {
91	        return owner.getEmail() != null && !owner.getEmail().isBlank();
92	    }
93	
94	    /**
95	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
96	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
97	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
98	     * case the field is absent from the response. The age in whole years is the number of complete
99	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
100	     * registration date is somehow absent the current date is used as the reference.
101	     *
102	     * @param owner the owner being mapped
103	     * @return the derived age band, or {@code null} when no birth date is present
104	     */
105	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
106	        java.time.LocalDate birthDate = owner.getBirthDate();
107	        if (birthDate == null) {
108	            return null;
109	        }
110	        java.time.LocalDate reference = owner.getRegistrationDate() != null
111	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
112	        int age = java.time.Period.between(birthDate, reference).getYears();
113	        if (age < 18) {
114	            return OwnerDto.AgeBandEnum.MINOR;
115	        }
116	        if (age < 65) {
117	            return OwnerDto.AgeBandEnum.ADULT;
118	        }
119	        return OwnerDto.AgeBandEnum.SENIOR;
120	    }
121	
122	    /**
123	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code memberId} (the
124	     * leading region-code prefix of the {@code '<REGION><FY><HASH8><CHK>'} identity). When no member id
125	     * is present (e.g. seed data) it falls back to resolving the region directly from the owner's
126	     * {@code postcode} and {@code city} through the shared {@link Region#code(String, String)}. Reading
127	     * the region from the identity keeps the locality consistent with the id an owner is issued.
128	     *
129	     * @param owner the owner being mapped
130	     * @return the derived locality
131	     */
132	    default String locality(Owner owner) {
133	        String memberId = owner.getMemberId();
134	        if (memberId == null) {
135	            return Region.code(owner.getPostcode(), owner.getCity());
136	        }
137	        return regionPrefix(memberId);
138	    }
139	
140	    /**
141	     * The {@code REGION} segment of a member id {@code '<REGION><FY><HASH8><CHK>'}: the leading
142	     * region-code prefix it was built from (e.g. {@code 'NSW'} for {@code 'NSW261A2B3C4D5'}). The region
143	     * code is one of the known {@link Region} names, otherwise {@link Region#UNKNOWN_CODE}, both of which
144	     * the member id always begins with, so the prefix is recovered by matching those known codes rather
145	     * than by a separator (the format carries none). Holding the "read the region back out of the
146	     * identity" rule in one place keeps the derived {@link #locality(Owner) locality} consistent with the
147	     * id an owner is issued.
148	     *
149	     * <p>Declared {@code private} so MapStruct treats it as an internal helper of {@link #locality(Owner)}
150	     * rather than as an implicit {@code String}-to-{@code String} mapping method it might auto-apply to
151	     * unrelated string properties.
152	     *
153	     * @param memberId the member id the region is read from
154	     * @return the leading {@code REGION} segment of the member id
155	     */
156	    private String regionPrefix(String memberId) {
157	        for (Region region : Region.values()) {
158	            if (memberId.startsWith(region.name())) {
159	                return region.name();
160	            }
161	        }
162	        return Region.UNKNOWN_CODE;
163	    }
164	
165	    /**
166	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
167	     * region, resolved through the shared fixed region-to-timezone table
168	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
169	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
170	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
171	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
172	     * region), in which case the field is absent from the response.
173	     *
174	     * @param owner the owner being mapped
175	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
176	     */
177	    default String timezone(Owner owner) {
178	        return Region.timezoneForCode(locality(owner));
179	    }
180	
181	    /**
182	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. {@code TIER} is
183	     * {@code PREMIUM} when the owner's {@link #membershipLevel(Owner) membershipLevel} is {@code 3} or
184	     * more, otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
185	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
186	     * {@code REGIONAL}. Deriving both parts from the same locality and membership level keeps the
187	     * segment consistent with those fields.
188	     *
189	     * @param owner the owner being mapped
190	     * @return the derived owner segment
191	     */
192	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
193	        return ownerSegment(owner, membershipLevel(owner));
194	    }
195	
196	    /**
197	     * Derives the owner's {@code ownerSegment} for a given reported {@code membershipLevel}, so a
198	     * caller that has shaped the level with cross-owner context (such as the controller's household
199	     * cap) can keep the segment's {@code TIER} consistent with the level it reports. {@code TIER} is
200	     * {@code PREMIUM} when {@code membershipLevel} is {@code 3} or more, otherwise {@code STANDARD};
201	     * {@code AREA} is {@code METRO} when the owner's {@link #locality(Owner) locality} is a known
202	     * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
203	     *
204	     * @param owner the owner being mapped
205	     * @param membershipLevel the membership level to base the tier on
206	     * @return the derived owner segment
207	     */
208	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner, int membershipLevel) {
209	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
210	        String area = Region.forCode(locality(owner)).isPresent() ? "METRO" : "REGIONAL";
211	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
212	    }
213	
214	    /**
215	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
216	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
217	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
218	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
219	     * of elapsed fiscal years between its {@code registrationDate} and the current date &mdash; exceeds
220	     * one fiscal year (see {@link #tenureFiscalYears(Owner)}).
221	     *
222	     * @param owner the owner being mapped
223	     * @return the derived membership points
224	     */
225	    default Integer membershipPoints(Owner owner) {
226	        int points = 0;
227	        if (hasEmail(owner)) {
228	            points += 2;
229	        }
230	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
231	        if (uniqueName) {
232	            points += 1;
233	        }
234	        if (owner.getHouseholdSize() >= 3) {
235	            points += 2;
236	        }
237	        if (tenureFiscalYears(owner) > 1) {
238	            points += 3;
239	        }
240	        return points;
241	    }
242	
243	    /**
244	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
245	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
246	     * {@code 4} for {@code 6} or more points.
247	     *
248	     * @param owner the owner being mapped
249	     * @return the derived membership level, between {@code 1} and {@code 4}
250	     */
251	    default Integer membershipLevel(Owner owner) {
252	        int points = membershipPoints(owner);
253	        if (points <= 1) {
254	            return 1;
255	        }
256	        if (points <= 3) {
257	            return 2;
258	        }
259	        if (points <= 5) {
260	            return 3;
261	        }
262	        return 4;
263	    }
264	
265	    /**
266	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
267	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
268	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
269	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
270	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
271	     * so an owner without a registration date has no tenure.
272	     *
273	     * @param owner the owner being mapped
274	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
275	     */
276	    default long tenureFiscalYears(Owner owner) {
277	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
278	        if (registrationDate == null) {
279	            return 0;
280	        }
281	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
282	    }
283	
284	    /**
285	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
286	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
287	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
288	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
289	     * yields {@code 2025}).
290	     *
291	     * @param date the date whose fiscal year is wanted
292	     * @return the calendar year the fiscal year starts in
293	     */
294	    default int fiscalYearNumber(java.time.LocalDate date) {
295	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
296	    }
297	
298	    /**
299	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the
300	     * {@code FY} segment of the owner's {@code memberId} (the two-digit fiscal year of the
301	     * business-day-adjusted {@code registrationDate} baked into the id, e.g. {@code 'FY26'}). When no
302	     * member id is present (e.g. seed data) it falls back to the segment derived directly from the
303	     * {@code registrationDate}. Returns {@code null} when neither is available.
304	     *
305	     * @param owner the owner being mapped
306	     * @return the formatted fiscal year, or {@code null} when it cannot be derived
307	     */
308	    default String fiscalYear(Owner owner) {
309	        String segment = memberIdFiscalYearSegment(owner);
310	        return segment == null ? null : "FY" + segment;
311	    }
312	
313	    /**
314	     * The two-digit {@code FY} segment of the owner's {@code fiscalYear}, read from the owner's
315	     * {@code memberId} when present so the reported fiscal year references the id an owner is issued: it
316	     * is the two characters immediately following the id's {@linkplain #regionPrefix(String) region
317	     * prefix}. When no member id is present (e.g. seed data) it falls back to the segment derived
318	     * directly from the {@code registrationDate} ({@link #fiscalYearSegment(Owner)}). Returns
319	     * {@code null} when neither is available.
320	     *
321	     * @param owner the owner being mapped
322	     * @return the two-digit fiscal-year segment, or {@code null} when it cannot be derived
323	     */
324	    default String memberIdFiscalYearSegment(Owner owner) {
325	        String memberId = owner.getMemberId();
326	        if (memberId == null) {
327	            return fiscalYearSegment(owner);
328	        }
329	        int start = regionPrefix(memberId).length();
330	        return memberId.substring(start, start + 2);
331	    }
332	
333	    /**
334	     * The two-digit {@code YY} fiscal-year segment of the owner's business-day-adjusted
335	     * {@code registrationDate}: the last two digits of its
336	     * {@linkplain #fiscalYearNumber(java.time.LocalDate) fiscal year}, zero-padded (e.g. {@code '26'}).
337	     * This is the {@code YY} baked into the {@code memberId} as its {@code FY} segment when the id is
338	     * built, and the fallback used by {@link #memberIdFiscalYearSegment(Owner)} for owners without a
339	     * member id, so the fiscal year derives identically either way. Returns {@code null} when no
340	     * registration date is present.
341	     *
342	     * @param owner the owner being mapped
343	     * @return the two-digit fiscal-year segment, or {@code null} when no registration date is present
344	     */
345	    default String fiscalYearSegment(Owner owner) {
346	        if (owner.getRegistrationDate() == null) {
347	            return null;
348	        }
349	        return String.format("%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
350	    }
351	
352	    /**
353	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
354	     * code, a space, then the national-significant digits grouped in threes separated by spaces
355	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
356	     * field keeps the unformatted E.164 value. The split between the country code and the national
357	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
358	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
359	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
360	     * {@code null}, blank, or not in E.164 form.
361	     *
362	     * @param owner the owner being mapped
363	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
364	     */
365	    default String telephoneDisplay(Owner owner) {
366	        String telephone = owner.getTelephone();
367	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
368	            return telephone;
369	        }
370	        String digits = telephone.substring(1);
371	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
372	        String countryCode = digits.substring(0, codeLength);
373	        String national = digits.substring(codeLength);
374	        StringBuilder grouped = new StringBuilder();
375	        for (int i = 0; i < national.length(); i++) {
376	            if (i > 0 && i % 3 == 0) {
377	                grouped.append(' ');
378	            }
379	            grouped.append(national.charAt(i));
380	        }
381	        return "+" + countryCode + " " + grouped;
382	    }
383	
384	    Owner toOwner(OwnerDto ownerDto);
385	
386	    @Mapping(target = "id", ignore = true)
387	    @Mapping(target = "pets", ignore = true)
388	    Owner toOwner(OwnerFieldsDto ownerDto);
389	
390	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
391	
392	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
393	
394	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
395	        OwnerPageDto ownerPageDto = new OwnerPageDto();
396	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
397	        ownerPageDto.setPage(ownerPage.getNumber());
398	        ownerPageDto.setSize(ownerPage.getSize());
399	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
400	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
401	        return ownerPageDto;
402	    }
403	}
