81	@RestController
82	@CrossOrigin(exposedHeaders = "errors, content-type")
83	@RequestMapping("/api")
84	public class OwnerRestControllerV1 implements OwnersApi {
85	
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    /**
89	     * Carries the welcome notification enqueued for each newly created owner. On a successful create a
90	     * single line is emitted on this dedicated {@code NOTIFY} logger naming the owner's id and
91	     * {@code memberId}, so the downstream welcome flow can be triggered without an
92	     * implementation-specific hook.
93	     */
94	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
95	
96	    /**
97	     * Serializes {@link OwnerCreatedEvent}s to the JSON carried on the {@code AUDIT} logger. A single
98	     * shared, thread-safe mapper so every structured audit event is rendered identically.
99	     */
100	    private static final ObjectMapper AUDIT_MAPPER = new ObjectMapper();
101	
102	    /**
103	     * Monotonically increasing sequence assigned to each owner create, carried as the {@code seq} of
104	     * the emitted {@link OwnerCreatedEvent} so the ordering of creates can be reconstructed from the
105	     * audit stream. Held per JVM and incremented atomically so concurrent creates receive distinct,
106	     * strictly increasing values.
107	     */
108	    private static final AtomicLong CREATE_SEQUENCE = new AtomicLong();
109	
110	    private final ClinicService clinicService;
111	
112	    private final OwnerMapper ownerMapper;
113	
114	    private final PetMapper petMapper;
115	
116	    private final VisitMapper visitMapper;
117	
118	    private final TelephoneNormalizer telephoneNormalizer;
119	
120	    private final AddressNormalizer addressNormalizer;
121	
122	    private final EmailNormalizer emailNormalizer;
123	
124	    private final DisposableEmailDomains disposableEmailDomains;
125	
126	    private final Sha256Hasher sha256Hasher;
127	
128	    private final Soundex soundex;
129	
130	    private final IdempotencyKeyStore idempotencyKeyStore;
131	
132	    public OwnerRestControllerV1(ClinicService clinicService,
133	                                 OwnerMapper ownerMapper,
134	                                 PetMapper petMapper,
135	                                 VisitMapper visitMapper,
136	                                 TelephoneNormalizer telephoneNormalizer,
137	                                 AddressNormalizer addressNormalizer,
138	                                 EmailNormalizer emailNormalizer,
139	                                 DisposableEmailDomains disposableEmailDomains,
140	                                 Sha256Hasher sha256Hasher,
141	                                 Soundex soundex,
142	                                 IdempotencyKeyStore idempotencyKeyStore) {
143	        this.clinicService = clinicService;
144	        this.ownerMapper = ownerMapper;
145	        this.petMapper = petMapper;
146	        this.visitMapper = visitMapper;
147	        this.telephoneNormalizer = telephoneNormalizer;
148	        this.addressNormalizer = addressNormalizer;
149	        this.emailNormalizer = emailNormalizer;
150	        this.disposableEmailDomains = disposableEmailDomains;
151	        this.sha256Hasher = sha256Hasher;
152	        this.soundex = soundex;
153	        this.idempotencyKeyStore = idempotencyKeyStore;
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
159	        Collection<Owner> owners;
160	        if (lastName != null) {
161	            owners = this.clinicService.findOwnerByLastName(lastName);
162	        } else {
163	            owners = this.clinicService.findAllOwners();
164	        }
165	        if (owners.isEmpty()) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
174	        return withOwner(ownerId, owner ->
175	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
176	    }
177	
178	    /**
179	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
180	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
181	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
182	     */
183	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
188	        String idempotencyKey = currentIdempotencyKey();
189	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
190	            .map(this.clinicService::findOwnerById);
191	        if (existing.isPresent()) {
192	            return ownerResponse(existing.get(), HttpStatus.OK);
193	        }
194	        Owner owner = createOwner(ownerFieldsDto);
195	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
196	        return ownerResponse(owner, HttpStatus.CREATED);
197	    }
198	
199	    /**
200	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
201	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
202	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
203	     * originally created owner.
204	     *
205	     * @return the request's idempotency key, or {@code null} when none was supplied
206	     */
207	    private String currentIdempotencyKey() {
208	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
209	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
210	        }
211	        return null;
212	    }
213	
214	    /**
215	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
216	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
217	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
218	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
219	     * then respond" and the persisted owner is available to callers that need it beyond the response.
220	     *
221	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
222	     * @return the persisted owner, with its derived fields populated
223	     */
224	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
225	        normalizeAddress(ownerFieldsDto);
226	        rejectBlankOwnerFields(ownerFieldsDto);
227	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
228	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
229	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
230	        rejectCityAtCapacity(ownerFieldsDto.getCity());
231	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
232	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
233	        rejectDailyRegistrationLimit(registrationDate);
234	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
235	        ownerFieldsDto.setTelephone(normalizedTelephone);
236	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
237	        ownerFieldsDto.setEmail(normalizedEmail);
238	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
239	        owner.setRegistrationDate(registrationDate);
240	        owner.setMemberId(memberId(owner));
241	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
242	        owner.setHouseholdId(householdId(owner));
243	        rejectDuplicateIdentity(owner);
244	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
245	        this.clinicService.saveOwner(owner);
246	        owner.setHouseholdSize(householdSize(owner));
247	        auditOwnerCreated(owner);
248	        enqueueWelcomeNotification(owner);
249	        return owner;
250	    }
251	
252	    /**
253	     * Enqueues the welcome notification for a just-created owner by emitting a single line on the
254	     * dedicated {@code NOTIFY} logger carrying the owner's id and {@code memberId}. Held separate from
255	     * the audit trail ({@link #auditOwnerCreated(Owner)}) so the welcome flow has its own single home
256	     * and the create pipeline reads as "make the owner, audit it, then welcome it".
257	     *
258	     * @param owner the persisted owner just created, with its derived fields populated
259	     */
260	    private void enqueueWelcomeNotification(Owner owner) {
261	        NOTIFY.info("Welcome notification enqueued: id={} memberId={}", owner.getId(), owner.getMemberId());
262	    }
263	
264	    /**
265	     * Records the audit trail for a just-created owner: the human-readable {@code AUDIT} line and, through
