462	    /**
463	     * Derives the read-only {@code riskFlag} for an owner: {@code true} when any of the soft risk
464	     * signals hold, otherwise {@code false}. The owner is at risk when it is a possible duplicate
465	     * (its {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} is set), when its email domain
466	     * is {@linkplain DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or when
467	     * its city is over its soft capacity (the same {@link #capacityWarning(String)} band that raises
468	     * {@code capacityWarning}). Combining the existing signals here keeps {@code riskFlag} as a single
469	     * derived summary computed in exactly one place alongside the fields it aggregates.
470	     *
471	     * @param owner the persisted owner to assess
472	     * @return {@code true} when any risk signal holds, otherwise {@code false}
473	     */
474	    private boolean riskFlag(Owner owner) {
475	        return owner.getPossibleDuplicateOf() != null
476	            || disposableEmailDomains.isDisposableAdjacent(owner.getEmail())
477	            || capacityWarning(owner.getCity());
478	    }
