480	    /**
481	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
482	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
483	     * routed through the controller so the create audit log and the single-owner response agree on one
484	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
485	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
486	     *
487	     * <p>Household ceiling: the reported level is capped at one above the current maximum
488	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
489	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
490	     * than the owner itself). With no existing household member no cap applies and the owner-local level
491	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
492	     * capped level), so it depends only on the members' own points and cannot recurse.
493	     *
494	     * @param owner the owner whose reported membership level is wanted
495	     * @return the owner's membership level, capped at one above its household maximum
496	     */
497	    private Integer membershipLevel(Owner owner) {
498	        int ownLevel = ownerMapper.membershipLevel(owner);
499	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
500	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
501	            .mapToInt(this::householdMemberLevel)
502	            .max();
503	        if (maxHouseholdLevel.isEmpty()) {
504	            return ownLevel;
505	        }
506	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
507	    }
508	
509	    /**
510	     * The owner-local membership level of a household member, used only as an input to the household
511	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
512	     * household size} is set from its household before the level is derived, so the member's household
513	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
514	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
515	     *
516	     * @param member an existing member of an owner's household
517	     * @return the member's owner-local membership level
518	     */
519	    private int householdMemberLevel(Owner member) {
520	        member.setHouseholdSize(householdSize(member));
521	        return ownerMapper.membershipLevel(member);
522	    }
