524	    /**
525	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
526	     * every later step - the required-field check, the persisted value and the response - sees the
527	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
528	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
529	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
530	     * steps that read the address.
531	     *
532	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
533	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
534	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
535	     * are preferred when present: the flat {@code address} returned is composed as the normalized
536	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
537	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
538	     * {@code address} retain its own normalized value.
539	     *
540	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
541	     */
542	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
543	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
544	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
545	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
546	        ownerFieldsDto.setAddressLine1(addressLine1);
547	        ownerFieldsDto.setAddressLine2(addressLine2);
548	        if (addressLine1 != null && !addressLine1.isBlank()) {
549	            String composed = addressLine2 != null && !addressLine2.isBlank()
550	                ? addressLine1 + " " + addressLine2
551	                : addressLine1;
552	            ownerFieldsDto.setAddress(composed);
553	        } else {
554	            ownerFieldsDto.setAddress(flatAddress);
555	        }
556	    }
