558	    /**
559	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
560	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
561	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
562	     * blank (e.g. {@code "   "}). The offending field names are reported through an
563	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
564	     * as a 400 response carrying an {@code errors} array of field names.
565	     *
566	     * @param ownerFieldsDto the submitted owner fields
567	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
568	     */
569	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
570	        List<String> blankFields = new ArrayList<>();
571	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
572	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
573	        addRequiredAddress(blankFields, ownerFieldsDto);
574	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
575	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
576	        if (!blankFields.isEmpty()) {
577	            throw new InvalidOwnerFieldsException(blankFields);
578	        }
579	    }
