587	    /**
588	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
589	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
590	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
591	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
592	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
593	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
594	     *
595	     * @param blankFields the accumulating list of blank required-field names
596	     * @param ownerFieldsDto the submitted owner fields
597	     */
598	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
599	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
600	            blankFields.add("address");
601	        }
