627	    /**
628	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
629	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
630	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
631	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
632	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
633	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
634	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
635	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
636	     *
637	     * @param city the city of the owner being created
638	     * @param postcode the supplied postcode, or {@code null} when omitted
639	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
640	     */
641	    private void rejectInvalidPostcode(String city, String postcode) {
642	        if (postcode == null || postcode.isBlank()) {
643	            return;
644	        }
645	        Region.forCity(city).ifPresent(region -> {
646	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
647	                throw new InvalidOwnerPostcodeException(postcode, city);
648	            }
649	        });
