652	    /**
653	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
654	     * the {@code memberId}.
655	     */
656	    private static final int MEMBER_ID_HASH_LENGTH = 8;
657	
658	    /**
659	     * Builds the unified {@code memberId} assigned to a newly created owner, formatted
660	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the owner's canonical region code resolved
661	     * from its {@code postcode} (falling back to its {@code city}) through the shared
662	     * {@link Region#code(String, String)}; {@code FY} is the two-digit fiscal year of the owner's
663	     * (business-day-adjusted) {@code registrationDate} ({@link OwnerMapper#fiscalYearSegment(Owner)});
664	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
665	     * normalized telephone followed by its last name; and {@code CHK} is a single Luhn check digit over
666	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). When this base id
667	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
668	     * {@code n} of 2 or more that makes the result unique (e.g. {@code 'NSW261A2B3C4D5-2'}), so distinct
669	     * owners always receive distinct member ids.
670	     *
671	     * @param owner the owner being created, with its telephone already normalized and its registration
672	     *              date set
673	     * @return the formatted, de-duplicated member id
674	     */
675	    private String memberId(Owner owner) {
676	        String region = Region.code(owner.getPostcode(), owner.getCity());
677	        String fiscalYear = ownerMapper.fiscalYearSegment(owner);
678	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), MEMBER_ID_HASH_LENGTH);
679	        String core = region + fiscalYear + hash8;
680	        String base = core + Luhn.checkDigit(core);
681	        return deduplicate(base, Owner::getMemberId);
682	    }
683	
684	    /**
685	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
686	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
687	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
688	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
689	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
690	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
691	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
692	     * caller supplies only which identifier it de-duplicates.
693	     *
694	     * @param base the computed base identifier to make unique among existing owners
695	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
696	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
697	     */
698	    private String deduplicate(String base, Function<Owner, String> identifier) {
699	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
700	            .map(identifier)
701	            .filter(java.util.Objects::nonNull)
702	            .collect(java.util.stream.Collectors.toSet());
703	        if (!existing.contains(base)) {
704	            return base;
705	        }
706	        int n = 2;
707	        while (existing.contains(base + "-" + n)) {
708	            n++;
709	        }
710	        return base + "-" + n;
711	    }
