713	    /**
714	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
715	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
716	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
717	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
718	     * new owner and surfaced as the read-only {@code namesakeCount} field.
719	     *
720	     * @param firstName the first name of the owner being created
721	     * @param lastName the last name of the owner being created
722	     * @return the number of existing owners with the same first and last name (case-insensitive)
723	     */
724	    private int namesakeCount(String firstName, String lastName) {
725	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
726	            && equalsIgnoreCase(owner.getLastName(), lastName));
727	    }
