740	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
741	     * owners. Existing owners are matched to the requested city case-insensitively (using
742	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
743	     * the per-city counting used for the member id. A city at capacity is reported through an
744	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
745	     * 409 Conflict response.
746	     *
747	     * @param city the city of the owner being created
748	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
749	     */
750	    private void rejectCityAtCapacity(String city) {
751	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
752	            throw new OwnerCityAtCapacityException(city);
753	        }
754	    }
755	
756	    /**
757	     * The soft per-city threshold at or above which the read-only {@code capacityWarning} flag is
758	     * raised. Once a city already holds this many owners (but fewer than the hard
759	     * {@link #MAX_OWNERS_PER_CITY} cap), it is flagged as approaching capacity - a warning well
760	     * below the hard rejection at {@link #MAX_OWNERS_PER_CITY}.
761	     */
762	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
763	
764	    /**
765	     * Derives the read-only {@code capacityWarning} flag for an owner: {@code true} when the owner's
766	     * city already holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and
767	     * {@link #MAX_OWNERS_PER_CITY} minus one owners (40 to 49, approaching the hard per-city capacity
768	     * limit of {@link #MAX_OWNERS_PER_CITY}), otherwise {@code false}. Uses the same per-city
769	     * accumulation as the hard capacity check ({@link #rejectCityAtCapacity(String)}), so the warning
770	     * band sits directly below the rejection at {@link #MAX_OWNERS_PER_CITY}.
771	     *
772	     * @param city the owner's city
773	     * @return {@code true} if the city is approaching, but has not reached, its owner capacity
774	     */
775	    private boolean capacityWarning(String city) {
776	        long owners = ownersInCity(city);
777	        return owners >= CITY_CAPACITY_WARNING_THRESHOLD && owners < MAX_OWNERS_PER_CITY;
778	    }
779	
780	    /**
781	     * Counts the existing owners whose {@code city} matches the given city, compared
782	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
783	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
784	     *
785	     * @param city the city to count owners for
786	     * @return the number of existing owners in that city
787	     */
788	    private long ownersInCity(String city) {
789	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
790	    }
791	
792	    /**
793	     * The maximum number of owners that may be registered on a single day. Once this many owners
794	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
795	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
796	     */
797	    private static final long MAX_OWNERS_PER_DAY = 100L;
798	
799	    /**
800	     * Resolves the effective registration date for a create request: the value supplied in the
801	     * request when present, otherwise the server's current date. The result is the raw effective
802	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
803	     *
804	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
805	     * @return the supplied date, or today when none was supplied
806	     */
807	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
808	        return suppliedDate != null ? suppliedDate : LocalDate.now();
809	    }
810	
811	    /**
812	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
813	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
814	     * today when omitted - but it may never be in the future. The check is applied to the raw
815	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
816	     * future date is rejected regardless of how that adjustment would move it. A future date is
817	     * reported through a {@link FutureRegistrationDateException}, which the
818	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
819	     * {@code registrationDate} field.
820	     *
821	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
822	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
823	     */
824	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
825	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
826	            throw new FutureRegistrationDateException(suppliedDate);
827	        }
828	    }
829	
830	    /**
831	     * The fixed list of public holidays that are not business days. A registration date that lands
832	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
833	     * business day, exactly as it is rolled forward off a weekend.
834	     */
835	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
836	        LocalDate.of(2026, 1, 1),
837	        LocalDate.of(2026, 1, 26),
838	        LocalDate.of(2026, 4, 25),
839	        LocalDate.of(2026, 12, 25),
840	        LocalDate.of(2026, 12, 28));
841	
842	    /**
843	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
844	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
845	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
846	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
847	     * value - whether supplied in the request or defaulted to the server date - is stored as the
848	     * next business day, and every value derived from the registration date (such as the membership
849	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
850	     *
851	     * @param date the effective registration date
852	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
853	     */
854	    private LocalDate businessDay(LocalDate date) {
855	        while (isNonBusinessDay(date)) {
856	            date = date.plusDays(1);
857	        }
858	        return date;
859	    }
860	
861	    /**
862	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
863	     *
864	     * @param date the date to test
865	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
866	     */
867	    private boolean isNonBusinessDay(LocalDate date) {
868	        DayOfWeek dayOfWeek = date.getDayOfWeek();
869	        return dayOfWeek == DayOfWeek.SATURDAY
870	            || dayOfWeek == DayOfWeek.SUNDAY
871	            || PUBLIC_HOLIDAYS.contains(date);
872	    }
873	
874	    /**
875	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
876	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
877	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
878	     * renders as a 429 Too Many Requests response.
879	     *
880	     * @param date the registration date of the owner being created (today)
881	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
882	     */
883	    private void rejectDailyRegistrationLimit(LocalDate date) {
884	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
885	            throw new DailyOwnerRegistrationLimitException(date);
886	        }
887	    }
888	
889	    /**
890	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
891	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
892	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
893	     * day's owners identically.
894	     *
895	     * @param date the registration date to count owners for
896	     * @return the number of existing owners registered on that day
897	     */
898	    private long ownersRegisteredOn(LocalDate date) {
899	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
900	    }
901	
902	    /**
903	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
904	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
905	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
906	     */
907	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
908	
909	    /**
910	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
911	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
912	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
913	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
914	     * without a registration date, such as seed data) is never flagged.
915	     *
916	     * @param date the owner's registration date (the day it was created), or {@code null}
917	     * @return {@code true} if the day already holds more than the warning threshold of owners
918	     */
919	    private boolean bulkSignupWarning(LocalDate date) {
920	        if (date == null) {
921	            return false;
922	        }
923	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
924	    }
925	
926	    /**
927	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
928	     * The identity key is the SHA-256 hex digest over
929	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
930	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
931	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
932	     * owners with the same last name and postcode but <em>different</em> telephones have different
933	     * identity keys and are both allowed (the second is surfaced instead as a soft
934	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
935	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
936	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
937	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
938	     * renders as a 409 Conflict response.
939	     *
940	     * @param owner the fully-populated owner being created (telephone normalized, email set)
941	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
942	     */
943	    private void rejectDuplicateIdentity(Owner owner) {
944	        String key = identityKey(owner);
945	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
946	        if (duplicate) {
947	            throw new DuplicateOwnerIdentityException(key);
948	        }
949	    }
950	
951	    /**
952	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
953	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
954	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
955	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
956	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
957	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
958	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
959	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
960	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
961	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
962	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
963	     *
964	     * @param owner the fully-populated owner being created (telephone normalized)
965	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
966	     */
967	    private Integer possibleDuplicateOf(Owner owner) {
968	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
969	            return null;
970	        }
971	        String key = identityKey(owner);
972	        String lastNameSoundex = soundex.encode(owner.getLastName());
973	        return this.clinicService.findAllOwners().stream()
974	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
975	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
976	                && !key.equals(identityKey(existing)))
977	            .map(Owner::getId)
978	            .filter(java.util.Objects::nonNull)
979	            .findFirst()
980	            .orElse(null);
981	    }
982	
983	    /**
984	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
985	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
986	     * the owner's telephone reduced to its canonical E.164 form (see
987	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
988	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
989	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
990	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
991	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
992	     * value across owners.
993	     *
994	     * @param owner the owner to derive the identity key for
995	     * @return the owner's identity key, a 64-character lower-case hex string
996	     */
997	    private String identityKey(Owner owner) {
998	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
999	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
1000	        String email = normalizedEmail == null ? "" : normalizedEmail;
1001	        String lastNameSoundex = soundex.encode(owner.getLastName());
1002	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
1003	    }
1004	
1005	    /**
1006	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
1007	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
1008	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
1009	     * checks reduce both an existing owner and the owner being created to the same canonical key;
1010	     * this returns the matched existing owner itself, so a caller can either reject the collision or
1011	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
1012	     * collision with only a deleted owner is not reported and the create is allowed.
1013	     *
1014	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
1015	     * @param key the canonical key of the owner being created
1016	     * @return the first existing owner sharing the key, or empty when none does
1017	     */
1018	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
1019	        return this.clinicService.findAllOwners().stream()
1020	            .filter(owner -> !owner.isDeleted())
1021	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
1022	            .findFirst();
1023	    }
1024	
1025	    /**
1026	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
1027	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
1028	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
1029	     * being created to the same canonical key and reject a match.
1030	     *
1031	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
1032	     * @param key the canonical key of the owner being created
1033	     * @return {@code true} if some existing owner shares the key
1034	     */
1035	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
1036	        return findExistingOwner(keyExtractor, key).isPresent();
1037	    }
1038	
1039	    /**
1040	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
1041	     * count-based rules - the per-city capacity, the per-day create limit and the derived
1042	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
1043	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
1044	     * place and each rule supplies just its own predicate.
1045	     *
1046	     * @param predicate the condition an owner must satisfy to be counted
1047	     * @return the number of existing owners that satisfy the predicate
1048	     */
1049	    private long countOwners(Predicate<Owner> predicate) {
1050	        return this.clinicService.findAllOwners().stream()
1051	            .filter(predicate)
1052	            .count();
1053	    }
1054	
1055	    /**
1056	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
1057	     * shared {@code householdId}.
1058	     */
1059	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
1060	
1061	    /**
1062	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1063	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1064	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1065	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1066	     *
1067	     * @param value the raw field value, or {@code null}
1068	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1069	     */
1070	    private String canonicalizeHousehold(String value) {
1071	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1072	    }
1073	
1074	    /**
1075	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1076	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1077	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1078	     * for the last-name normalization), so every owner with the same last name and postcode -
1079	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1080	     * a postcode have no household basis and are given no household id ({@code null}).
1081	     *
1082	     * @param owner the owner being created
1083	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1084	     */
1085	    /**
1086	     * Counts the owners in the given owner's household: the existing owners that share its
1087	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1088	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1089	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1090	     * household factor of the owner's membership points.
1091	     *
1092	     * @param owner the owner whose household size is being derived
1093	     * @return the number of owners in the owner's household (at least {@code 1})
1094	     */
1095	    private int householdSize(Owner owner) {
1096	        if (owner.getHouseholdId() == null) {
1097	            return 1;
1098	        }
1099	        return householdMembers(owner).size();
1100	    }
1101	
1102	    /**
1103	     * The existing owners that make up the given owner's household: those sharing its
1104	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1105	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1106	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1107	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1108	     * counts it among its household, while one taken before the save sees only the owners already
1109	     * present. Holding the household lookup in one place lets every household-derived value read the
1110	     * same set of members.
1111	     *
1112	     * @param owner the owner whose household members are wanted
1113	     * @return the owners sharing the owner's household, or an empty list when it has no household
1114	     */
1115	    private List<Owner> householdMembers(Owner owner) {
1116	        String household = owner.getHouseholdId();
1117	        if (household == null) {
1118	            return List.of();
1119	        }
1120	        return this.clinicService.findAllOwners().stream()
1121	            .filter(existing -> household.equals(existing.getHouseholdId()))
1122	            .toList();
1123	    }
1124	
1125	    private String householdId(Owner owner) {
1126	        String postcode = owner.getPostcode();
1127	        if (postcode == null || postcode.isBlank()) {
1128	            return null;
1129	        }
1130	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1131	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1132	    }
1133	
1134	    /**
1135	     * Number of leading hex characters of the household hash retained as the shared
1136	     * {@code householdId}.
1137	     */
1138	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1139	}
